// Sample content for the Model Studio mockups (labelled as sample in the UI). Shapes follow the real spec rules:
// item cuboids in item-model space (0-16, -16..32 allowed), RigSpec creatures in Blockbench units (16 = 1 block),
// one skin per model with box UV (compile.ts boxFaces), single-axis 22.5-degree element rotations for item models.
(function () {
  const { raster, hex, setPx, layout, hash, mix } = M3;
  const MAT = {
    polymer: { base: "#2b2c33", hi: "#4a4d58", lo: "#18191e", pat: "noise", rough: 0.75 },
    slide: { base: "#33353d", hi: "#5a5e6b", lo: "#1d1e23", pat: "serr", rough: 0.45, metal: 0.6 },
    metal: { base: "#70737e", hi: "#a3a7b4", lo: "#43454d", pat: "streak", rough: 0.35, metal: 0.9 },
    grip: { base: "#24252b", hi: "#3a3c45", lo: "#141418", pat: "stipple", rough: 0.9 },
    sight: { base: "#2a2b31", hi: "#ff8a1f", lo: "#16161a", pat: "dot", rough: 0.6 },
    wood: { base: "#8a4f2a", hi: "#b26d3d", lo: "#5c311a", pat: "grain", rough: 0.7 },
    steel: { base: "#3d3f46", hi: "#62656f", lo: "#232429", pat: "streak", rough: 0.4, metal: 0.85 },
    mag: { base: "#33302c", hi: "#4f4a43", lo: "#1d1b18", pat: "ribs", rough: 0.6, metal: 0.5 },
    ghost: { base: "#cfe9e6", hi: "#f1fffb", lo: "#7fb2b4", pat: "fade", rough: 0.9 },
    hood: { base: "#3b3352", hi: "#5a4f7a", lo: "#221c33", pat: "noise", rough: 0.9 },
    face: { base: "#e4f5f1", hi: "#ffffff", lo: "#a9cfcb", pat: "noise", rough: 0.9 },
    eye: { base: "#b9ffd9", hi: "#ffffff", lo: "#6ee7b7", pat: "flat", rough: 0.9, emis: 1 },
    veil: { base: "#a9d6d3", hi: "#d8f3ef", lo: "#5e8f93", pat: "tatter", rough: 0.9 },
    skin: { base: "#c99a78", hi: "#dcb393", lo: "#a67b5c", pat: "flat" }, shirt: { base: "#3d4b70", hi: "#566796", lo: "#2a3452", pat: "noise" },
    pants: { base: "#2b2f45", hi: "#3b4060", lo: "#1c1f2e", pat: "noise" }, hair: { base: "#3a2a1e", hi: "#523c2b", lo: "#251a12", pat: "noise" },
  };
