      case "tatter": { c = mix(b, lo, Math.min(1, j / Math.max(1, H - 1)) * 0.9); const cut = H - 1 - Math.floor(hash(i, 7, seed) * 3); if (face !== "up" && face !== "down" && j > cut) return null; break; }
