      { name: "sight_f", from: [13.8, 11.5, 7.7], to: [14.6, 12.2, 8.3], m: "sight" },
      { name: "sight_r", from: [3.3, 11.5, 7.4], to: [4.5, 12.2, 8.6], m: "polymer" },
      { name: "mag_base", from: [2.4, 1.2, 7.05], to: [5.6, 2, 8.95], m: "polymer", rot: { axis: "z", angle: 22.5, origin: [5.5, 7.5, 8] } },
    ],
  };
