      { name: "receiver", from: [-2, 8, 7], to: [12, 11, 9], m: "steel" },
      { name: "dust_cover", from: [-1.5, 11, 7.2], to: [10, 11.8, 8.8], m: "steel" },
      { name: "handguard", from: [12, 8.4, 6.8], to: [20, 10.6, 9.2], m: "wood" },
      { name: "gas_tube", from: [12, 10.6, 7.4], to: [21, 11.6, 8.6], m: "steel" },
      { name: "barrel", from: [20, 8.9, 7.5], to: [29, 9.9, 8.5], m: "metal" },
      { name: "sight_f", from: [26.5, 9.9, 7.6], to: [27.5, 12, 8.4], m: "steel" },
      { name: "muzzle", from: [29, 8.7, 7.3], to: [31, 10.1, 8.7], m: "steel" },
      { name: "stock", from: [-14, 5.5, 7.1], to: [-2, 9.6, 8.9], m: "wood", rot: { axis: "z", angle: -22.5, origin: [-2, 8.5, 8] } },
      { name: "grip", from: [-0.5, 2.5, 7.2], to: [2, 8, 8.8], m: "wood", rot: { axis: "z", angle: 22.5, origin: [0.75, 8, 8] } },
      { name: "mag_top", from: [4, 3.5, 7.2], to: [7.5, 8, 8.8], m: "mag", rot: { axis: "z", angle: -22.5, origin: [5.75, 8, 8] } },
      { name: "mag_low", from: [6.6, -1.4, 7.2], to: [10, 3.9, 8.8], m: "mag", rot: { axis: "z", angle: -45, origin: [5.75, 8, 8] } },
      { name: "trigger", from: [2.5, 6.5, 7.7], to: [3.3, 8, 8.3], m: "metal" },
    ],
  };
  // fire sticker decal layer: flame tongues on the side faces of the named elements (a texture layer, not geometry)
  function fireDecals(spec, skin, on) {
    if (!on) return;
    const targets = { receiver: 1, stock: 1, handguard: 1, dust_cover: 1 };
    spec.elements.forEach((c, k) => {
      if (!targets[c.name]) return;
      for (const f of ["north", "south"]) {
        const rc = c._lay.faces[f];
        for (let i = 0; i < rc.w; i++) {
          const t = (f === "north" ? rc.w - 1 - i : i) / rc.w;
          const hgt = Math.max(0, (Math.sin(t * 19 + k) * 0.5 + 0.5) * 0.55 + 0.25 - (c.name === "dust_cover" ? 0.4 : 0)) * rc.h;
          for (let j = 0; j < rc.h; j++) {
            const fromBottom = rc.h - 1 - j;
            if (fromBottom < hgt) { const q = fromBottom / Math.max(1, hgt); const col = q > 0.72 ? [255, 214, 92] : q > 0.4 ? [255, 138, 31] : [214, 52, 32]; setPx(skin, rc.x + i, rc.y + j, col); }
          }
        }
      }
    });
  }
  // ---------------- banshee (RigSpec floating_ghost, explicit form). Absolute Blockbench coords, faces -z.
  const BANSHEE = {
    key: "banshee", kind: "creature", size: 128, dens: 1, archetype: "floating_ghost", baseEntity: "VEX",
    bones: [
      { name: "root", parent: null, pivot: [0, 0, 0], cubes: [] },
      { name: "body", parent: "root", pivot: [0, 14, 0], cubes: [{ from: [-4, 12, -2.5], to: [4, 22, 2.5], m: "ghost" }] },
      { name: "veil", parent: "body", pivot: [0, 12, 0], cubes: [{ from: [-5, 3, -3.5], to: [5, 13, 3.5], m: "veil" }, { from: [-3.5, 0, -2.5], to: [3.5, 4, 2.5], m: "veil" }] },
      { name: "head", parent: "body", pivot: [0, 22, 0], tag: "head", cubes: [{ from: [-3.5, 22, -3.5], to: [3.5, 29, 3.5], m: "face" }] },
      { name: "hood", parent: "head", pivot: [0, 22, 0], cubes: [{ from: [-4, 23, -2.2], to: [4, 30, 4.2], m: "hood", inflate: 0.4 }, { from: [-4.4, 29.4, -3.9], to: [4.4, 30.6, 0], m: "hood" }] },
      { name: "eyes", parent: "head", pivot: [0, 25, -3.6], tag: "glow", cubes: [{ from: [-2.6, 25, -3.7], to: [-0.8, 26, -3.5], m: "eye" }, { from: [0.8, 25, -3.7], to: [2.6, 26, -3.5], m: "eye" }] },
      { name: "arm_l", parent: "body", pivot: [5, 21, 0], cubes: [{ from: [4, 10, -1.5], to: [7, 22, 1.5], m: "ghost" }, { from: [4.2, 6.5, -1.2], to: [6.8, 10, 1.2], m: "veil" }] },
      { name: "arm_r", parent: "body", pivot: [-5, 21, 0], cubes: [{ from: [-7, 10, -1.5], to: [-4, 22, 1.5], m: "ghost" }, { from: [-6.8, 6.5, -1.2], to: [-4.2, 10, 1.2], m: "veil" }] },
    ],
    clips: {
      idle: { length: 2.4, loop: true, tracks: [{ bone: "root", ch: "position", keys: [[0, [0, 0, 0]], [0.5, [0, 1.4, 0]], [1, [0, 0, 0]]] }, { bone: "arm_l", ch: "rotation", keys: [[0, [0, 0, -6]], [0.5, [6, 0, -12]], [1, [0, 0, -6]]] }, { bone: "arm_r", ch: "rotation", keys: [[0, [0, 0, 6]], [0.5, [6, 0, 12]], [1, [0, 0, 6]]] }, { bone: "veil", ch: "rotation", keys: [[0, [4, 0, 0]], [0.5, [-4, 0, 0]], [1, [4, 0, 0]]] }, { bone: "head", ch: "rotation", keys: [[0, [0, -8, 0]], [0.5, [3, 8, 0]], [1, [0, -8, 0]]] }] },
      walk: { length: 1.2, loop: true, tracks: [{ bone: "root", ch: "position", keys: [[0, [0, 0, 0]], [0.5, [0, 0.8, 0]], [1, [0, 0, 0]]] }, { bone: "veil", ch: "rotation", keys: [[0, [14, 0, 0]], [1, [14, 0, 0]]] }] },
      attack: { length: 0.8, loop: false, tracks: [{ bone: "arm_l", ch: "rotation", keys: [[0, [0, 0, 0]], [0.35, [-110, 0, -10]], [1, [0, 0, 0]]] }, { bone: "arm_r", ch: "rotation", keys: [[0, [0, 0, 0]], [0.35, [-110, 0, 10]], [1, [0, 0, 0]]] }] },
      hurt: { length: 0.4, loop: false, tracks: [{ bone: "body", ch: "rotation", keys: [[0, [0, 0, 0]], [0.4, [12, 0, 0]], [1, [0, 0, 0]]] }] },
      death: { length: 1.6, loop: false, tracks: [{ bone: "root", ch: "position", keys: [[0, [0, 0, 0]], [1, [0, -6, 0]]] }, { bone: "body", ch: "rotation", keys: [[0, [0, 0, 0]], [1, [70, 0, 0]]] }] },
    },
  };
  // a blocky player (hand previews): Blockbench units, feet at 0
  const PLAYER = [
    { name: "head", from: [-4, 24, -4], to: [4, 32, 4], m: "skin" }, { name: "hair", from: [-4.2, 29, -4.2], to: [4.2, 32.3, 4.2], m: "hair" },
    { name: "body", from: [-4, 12, -2], to: [4, 24, 2], m: "shirt" },
    { name: "leg_r", from: [-4, 0, -2], to: [0, 12, 2], m: "pants" }, { name: "leg_l", from: [0, 0, -2], to: [4, 12, 2], m: "pants" },
  ];
  const ARM = (side) => ({ name: "arm_" + side, from: [side === "r" ? -8 : 4, 12, -2], to: [side === "r" ? -4 : 8, 24, 2], m: "shirt" });

  function elemMatrix(c) {
    if (!c.rot) return M3.I4();
    const r = [0, 0, 0]; r[{ x: 0, y: 1, z: 2 }[c.rot.axis]] = c.rot.angle;
    return M3.about(c.rot.origin, r);
  }
  // item -> polys in "block" units (1 = 16 item units), centred on the item origin [8,8,8]
  function itemPolys(spec, skin, M, extra) {
    const out = [];
    for (const c of spec.elements) {
      const off = c.off || [0, 0, 0];
      const m = M3.mm(M, M3.mm(M3.S(1 / 16, 1 / 16, 1 / 16), M3.mm(M3.T(-8 + off[0], -8 + off[1], -8 + off[2]), elemMatrix(c))));
      M3.cuboid(out, c, m, skin, { ...extra, el: c.name, mat: MAT[c.m] });
    }
    return out;
  }
  // creature pose: bone world matrices (rest rotation + clip sample), Euler ZYX like Blockbench
  function sampleKeys(keys, t) {
    if (t <= keys[0][0]) return keys[0][1]; for (let i = 0; i < keys.length - 1; i++) { const [ta, va] = keys[i], [tb, vb] = keys[i + 1]; if (t <= tb) { const u = (t - ta) / (tb - ta), s = u * u * (3 - 2 * u); return va.map((v, k) => v + (vb[k] - v) * s); } }
    return keys[keys.length - 1][1];
  }
  function pose(spec, clip, t) {
    const out = new Map(), C = clip && spec.clips[clip], byName = Object.fromEntries(spec.bones.map((b) => [b.name, b]));
    const anim = (b, ch) => { const tr = C && C.tracks.find((x) => x.bone === b.name && x.ch === ch); return tr ? sampleKeys(tr.keys, t) : [0, 0, 0]; };
    const W = (b) => {
      if (out.has(b.name)) return out.get(b.name);
      const parent = b.parent ? W(byName[b.parent]) : M3.I4();
      const rot = (b.rotation || [0, 0, 0]).map((v, i) => v + anim(b, "rotation")[i]), pos = anim(b, "position");
      const m = M3.mm(parent, M3.mm(M3.T(...pos), M3.about(b.pivot, rot)));
      out.set(b.name, m); return m;
    };
    spec.bones.forEach(W); return out;
  }
  function creaturePolys(spec, skin, clip, t, M) {
    const P = pose(spec, clip, t), out = [];
    for (const b of spec.bones) for (const [i, c] of b.cubes.entries()) M3.cuboid(out, c, M3.mm(M, M3.mm(M3.S(1 / 16, 1 / 16, 1 / 16), P.get(b.name))), skin, { bone: b.name, ci: i, mat: MAT[c.m] });
    return out;
  }
  function allCubes(spec) { return spec.elements || spec.bones.flatMap((b) => b.cubes); }
  function prep(spec) { const cubes = allCubes(spec); M3.layout(cubes, spec.size, spec.dens); return bake(cubes, spec.size); }
  Object.assign(window.MODELS, { GUN, RIFLE, BANSHEE, PLAYER, ARM, itemPolys, creaturePolys, pose, prep, allCubes, fireDecals, elemMatrix, sampleKeys });

  // ---------------- livery sedan: a lofted UV-mapped triangle mesh (stand-in for an imported, user-supplied glTF template)
  function carMesh() {
    const NU = 72, NV = 30, L = 4.6, out = [];
    const top = (u) => { const pts = [[0, 0.62], [0.06, 0.8], [0.3, 0.92], [0.4, 1.36], [0.47, 1.45], [0.7, 1.45], [0.82, 1.08], [0.92, 1.02], [1, 0.78]]; for (let i = 0; i < pts.length - 1; i++) if (u <= pts[i + 1][0]) { const k = (u - pts[i][0]) / (pts[i + 1][0] - pts[i][0]); const s = k * k * (3 - 2 * k); return pts[i][1] + (pts[i + 1][1] - pts[i][1]) * s; } return 0.78; };
    const bottom = 0.26, belt = 0.98;
    const halfW = (u, y) => { const end = Math.min(1, Math.min(u, 1 - u) / 0.06); let w = 0.93 * (0.78 + 0.22 * Math.sqrt(Math.max(0, end))); if (y > belt) w *= 1 - 0.24 * Math.min(1, (y - belt) / 0.45); return w; };
    const P = (u, v) => { // v around the section: 0 = bottom centre, 0.25 = right side, 0.5 = top, 0.75 = left
      const a = v * Math.PI * 2, ca = -Math.cos(a), sa = Math.sin(a);
      const yc = (top(u) + bottom) / 2, hh = (top(u) - bottom) / 2;
      const y = yc + hh * Math.sign(ca) * Math.pow(Math.abs(ca), 0.42);
      const z = halfW(u, y) * Math.sign(sa) * Math.pow(Math.abs(sa), 0.3);
      return [(u - 0.5) * L, y, z];
    };
    const isle = (n, c) => (n[1] > 0.62 ? "top" : n[0] > 0.6 ? "front" : n[0] < -0.6 ? "rear" : c[2] > 0 ? "side_r" : "side_l");
    const RECT = { side_l: [16, 16, 992, 250], side_r: [16, 282, 992, 250], top: [16, 548, 620, 200], front: [660, 548, 166, 200], rear: [842, 548, 166, 200] };
    const uvOf = (p, is) => { const [x, y, z] = p, r = RECT[is]; let a, b; if (is === "side_l") { a = x / L + 0.5; b = 1 - (y - 0.2) / 1.3; } else if (is === "side_r") { a = 0.5 - x / L; b = 1 - (y - 0.2) / 1.3; } else if (is === "top") { a = x / L + 0.5; b = 0.5 + z / 2; } else if (is === "front") { a = 0.5 - z / 2; b = 1 - (y - 0.2) / 1.3; } else { a = 0.5 + z / 2; b = 1 - (y - 0.2) / 1.3; } return [(r[0] + Math.max(0, Math.min(1, a)) * r[2]) / 1024, (r[1] + Math.max(0, Math.min(1, b)) * r[3]) / 768]; };
    for (let i = 0; i < NU; i++) for (let j = 0; j < NV; j++) {
      const u0 = i / NU, u1 = (i + 1) / NU, v0 = j / NV, v1 = (j + 1) / NV;
      const a = P(u0, v0), b = P(u1, v0), c = P(u1, v1), d = P(u0, v1);
      for (const tri of [[a, b, c], [a, c, d]]) {
        const n = M3.norm(M3.cross(M3.sub(tri[1], tri[0]), M3.sub(tri[2], tri[0])));
        const cen = [0, 1, 2].map((k) => (tri[0][k] + tri[1][k] + tri[2][k]) / 3);
        const um = (u0 + u1) / 2, glass = cen[1] > belt + 0.05 && um > 0.36 && um < 0.83 && n[1] < 0.9 && !(um > 0.52 && um < 0.56 && Math.abs(n[1]) < 0.6);
        const light = (um < 0.035 || um > 0.968) && cen[1] > 0.58 && cen[1] < 0.76 && Math.abs(cen[2]) > 0.45;
        const slot = glass ? "glass" : light ? (um < 0.5 ? "lights_r" : "lights_f") : cen[1] < 0.36 ? "trim" : "body_paint";
        const is = isle(n, cen), uv = uvOf(cen, is);
        out.push({ p: tri, n, slot, isle: is, uvx: uv[0], uvy: uv[1], uvs: tri.map((p) => uvOf(p, is)), ao: Math.min(1, 0.55 + (cen[1] - 0.2) * 0.6) });
      }
    }
    // wheels
    for (const [wx, wz] of [[-1.42, 1], [1.38, 1], [-1.42, -1], [1.38, -1]]) {
      const N = 18, rr = 0.36, wd = 0.24, z0 = wz * 0.72, z1 = wz * (0.72 + wd);
      for (let k = 0; k < N; k++) {
        const a0 = (k / N) * Math.PI * 2, a1 = ((k + 1) / N) * Math.PI * 2;
        const p = (a, z) => [wx + Math.cos(a) * rr, 0.36 + Math.sin(a) * rr, z];
        const ring = [p(a0, z0), p(a1, z0), p(a1, z1), p(a0, z1)];
        out.push({ p: wz > 0 ? ring : [...ring].reverse(), n: [Math.cos((a0 + a1) / 2), Math.sin((a0 + a1) / 2), 0], slot: "tyre" });
        const cap = [[wx, 0.36, z1], p(a0, z1), p(a1, z1)];
        out.push({ p: wz > 0 ? cap : [cap[0], cap[2], cap[1]], n: [0, 0, wz], slot: k % 3 === 0 ? "tyre" : "rim", rimk: k });
      }
    }
    return { tris: out, RECT };
  }
  const SLOTS = {
    body_paint: { label: "body_paint", mat: { rough: 0.22, metal: 0.55 } }, glass: { label: "glass", mat: { rough: 0.05, metal: 0.1 }, c: [24, 28, 44] },
    trim: { label: "trim", mat: { rough: 0.7, metal: 0.1 }, c: [30, 30, 36] }, tyre: { label: "tyre", mat: { rough: 0.95 }, c: [22, 22, 26] },
    rim: { label: "rim", mat: { rough: 0.3, metal: 0.95 }, c: [150, 154, 168] }, lights_f: { label: "lights_front", mat: { rough: 0.1, emis: 1 }, c: [255, 246, 214] }, lights_r: { label: "lights_rear", mat: { rough: 0.1, emis: 1 }, c: [255, 64, 84] },
  };
  Object.assign(window.MODELS, { carMesh, SLOTS });
})();

